children.blockClientScript:
let showMoreIntro = false;

this.onclick = () => {
  showMoreIntro = !showMoreIntro;
  const introContent = document.getElementById("intro-content");
  const textEl = this.querySelector("p");

  if (introContent) {
    if (showMoreIntro) {
      introContent.style.setProperty("-webkit-line-clamp", "none");
      textEl.textContent = "See less";
    } else {
      introContent.style.setProperty("-webkit-line-clamp", 3);
      textEl.textContent = "See more";
    }
  }
};
